import type { LogEntry, WorkflowRunState } from '../../types';

// ─── Develop renderer types ─────────────────────────────────────────────────

export interface DevelopPhaseInfo {
  id: string;
  label: string;
  icon: string;
  status: 'completed' | 'active' | 'pending';
}

export interface DevelopAgentInfo {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface DevelopRendererState {
  phases: DevelopPhaseInfo[];
  agents: DevelopAgentInfo[];
  currentPhase: string;
}

// ─── Helper ─────────────────────────────────────────────────────────────────

export function buildDevelopState(runState: WorkflowRunState): DevelopRendererState {
  const phases: DevelopPhaseInfo[] = [];
  const sidebarPhases = runState.summary.sidebar.phases;
  if (sidebarPhases) {
    for (const phase of sidebarPhases) {
      let status: 'completed' | 'active' | 'pending';
      if (runState.completedPhases.includes(phase.id)) {
        status = 'completed';
      } else if (phase.id === runState.currentPhase) {
        status = 'active';
      } else {
        status = 'pending';
      }
      phases.push({
        id: phase.id,
        label: phase.label,
        icon: phase.icon,
        status,
      });
    }
  }

  const agents: DevelopAgentInfo[] = [];
  for (const [agentId, agent] of runState.agents) {
    agents.push({
      agentId: agent.agentId,
      profile: agent.profile,
      taskId: agent.taskId,
      active: agent.active,
      log: agent.log,
    });
  }
  agents.sort((a, b) => a.agentId.localeCompare(b.agentId));

  return {
    phases,
    agents,
    currentPhase: runState.currentPhase,
  };
}

import './ProgressIndicator.css';
import type { DevelopPhaseInfo } from './types';

interface ProgressIndicatorProps {
  phases: DevelopPhaseInfo[];
}

export function ProgressIndicator({ phases }: ProgressIndicatorProps) {
  return (
    <div className="progress-indicator">
      {phases.map((phase, index) => (
        <div key={phase.id} className={`phase-item ${phase.status}`}>
          <span className="phase-icon">
            {phase.status === 'completed' ? '✅' : phase.icon}
          </span>
          <span className="phase-label">{phase.label}</span>
          {index < phases.length - 1 && (
            <div
              className={`phase-connector ${phase.status === 'completed' ? 'completed' : 'pending'}`}
            />
          )}
        </div>
      ))}
    </div>
  );
}

.progress-indicator {
  display: flex;
  align-items: center;
  padding: var(--engin-space-sm) var(--engin-space-md);
  background: var(--engin-bg-secondary);
  border-bottom: 1px solid var(--engin-border);
  overflow-x: auto;
  gap: var(--engin-space-xs);
  flex-shrink: 0;
}

.phase-item {
  display: flex;
  align-items: center;
  gap: var(--engin-space-xs);
  white-space: nowrap;
  font-size: 12px;
}

.phase-icon {
  font-size: 14px;
  line-height: 1;
}

.phase-label {
  font-size: 12px;
  line-height: 1;
}

/* ── Status: completed ──────────────────────────────────────────────────── */

.phase-item.completed .phase-icon {
  color: var(--engin-success);
}

.phase-item.completed .phase-label {
  color: var(--engin-text-muted);
}

/* ── Status: active ─────────────────────────────────────────────────────── */

.phase-item.active .phase-icon {
  color: var(--engin-accent);
}

.phase-item.active .phase-label {
  color: var(--engin-accent);
  font-weight: 700;
}

.phase-item.active {
  background: var(--engin-bg-hover);
  border-radius: var(--engin-radius-sm);
  padding: 2px 4px;
}

/* ── Status: pending ────────────────────────────────────────────────────── */

.phase-item.pending .phase-icon {
  opacity: 0.4;
}

.phase-item.pending .phase-label {
  color: var(--engin-text-muted);
}

/* ── Connector ──────────────────────────────────────────────────────────── */

.phase-connector {
  width: 20px;
  height: 1px;
  flex-shrink: 0;
}

.phase-connector.completed {
  background: var(--engin-success);
}

.phase-connector.pending {
  background: var(--engin-border);
}

/**
 * Tests for ProgressIndicator component.
 *
 * Verifies that the horizontal phase bar renders phases with correct
 * styling based on status (completed / active / pending) and that
 * connector lines appear between phases with appropriate color.
 */

import '@testing-library/jest-dom/vitest';

import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';

import { ProgressIndicator } from '../ProgressIndicator';
import type { DevelopPhaseInfo } from '../types';

// ─── Helpers ────────────────────────────────────────────────────────────────

function createPhase(
  overrides: Partial<DevelopPhaseInfo> = {},
): DevelopPhaseInfo {
  return {
    id: 'phase-1',
    label: 'Phase 1',
    icon: '📋',
    status: 'pending',
    ...overrides,
  };
}

// ─── Tests ──────────────────────────────────────────────────────────────────

describe('ProgressIndicator', () => {
  describe('rendering phases', () => {
    it('renders each phase label', () => {
      const phases = [
        createPhase({ id: 'a', label: 'Alpha' }),
        createPhase({ id: 'b', label: 'Beta' }),
        createPhase({ id: 'c', label: 'Gamma' }),
      ];
      render(<ProgressIndicator phases={phases} />);
      expect(screen.getByText('Alpha')).toBeInTheDocument();
      expect(screen.getByText('Beta')).toBeInTheDocument();
      expect(screen.getByText('Gamma')).toBeInTheDocument();
    });

    it('renders phase icons for non-completed phases', () => {
      const phases = [
        createPhase({ id: 'a', icon: '🔍', status: 'active' }),
        createPhase({ id: 'b', icon: '⚙️', status: 'pending' }),
      ];
      render(<ProgressIndicator phases={phases} />);
      expect(screen.getByText('🔍')).toBeInTheDocument();
      expect(screen.getByText('⚙️')).toBeInTheDocument();
    });

    it('shows a checkmark (✅) for completed phases instead of the original icon', () => {
      const phases = [
        createPhase({ id: 'a', icon: '📋', status: 'completed' }),
      ];
      render(<ProgressIndicator phases={phases} />);
      expect(screen.getByText('✅')).toBeInTheDocument();
      expect(screen.queryByText('📋')).not.toBeInTheDocument();
    });

    it('renders nothing when phases array is empty', () => {
      const { container } = render(<ProgressIndicator phases={[]} />);
      const indicator = container.querySelector('.progress-indicator');
      expect(indicator).toBeInTheDocument();
      expect(indicator?.children.length).toBe(0);
    });

    it('renders the correct number of phase items', () => {
      const phases = [
        createPhase({ id: 'a' }),
        createPhase({ id: 'b' }),
        createPhase({ id: 'c' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const items = container.querySelectorAll('.phase-item');
      expect(items).toHaveLength(3);
    });
  });

  describe('status styling', () => {
    it('applies "completed" class for completed phases', () => {
      const phases = [createPhase({ status: 'completed' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item');
      expect(item).toHaveClass('completed');
      expect(item).not.toHaveClass('active');
      expect(item).not.toHaveClass('pending');
    });

    it('applies "active" class for active phases', () => {
      const phases = [createPhase({ status: 'active' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item');
      expect(item).toHaveClass('active');
      expect(item).not.toHaveClass('completed');
      expect(item).not.toHaveClass('pending');
    });

    it('applies "pending" class for pending phases', () => {
      const phases = [createPhase({ status: 'pending' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item');
      expect(item).toHaveClass('pending');
      expect(item).not.toHaveClass('completed');
      expect(item).not.toHaveClass('active');
    });
  });

  describe('connectors', () => {
    it('renders a connector between each pair of phases', () => {
      const phases = [
        createPhase({ id: 'a' }),
        createPhase({ id: 'b' }),
        createPhase({ id: 'c' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connectors = container.querySelectorAll('.phase-connector');
      expect(connectors).toHaveLength(2); // 3 phases → 2 connectors
    });

    it('does not render a connector after the last phase', () => {
      const phases = [
        createPhase({ id: 'a' }),
        createPhase({ id: 'b' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const lastItem = container.querySelector('.phase-item:last-child');
      expect(lastItem?.querySelector('.phase-connector')).toBeNull();
    });

    it('renders no connectors when there is only one phase', () => {
      const phases = [createPhase({ id: 'a' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connectors = container.querySelectorAll('.phase-connector');
      expect(connectors).toHaveLength(0);
    });

    it('applies "completed" class to connector after a completed phase', () => {
      const phases = [
        createPhase({ id: 'a', status: 'completed' }),
        createPhase({ id: 'b', status: 'active' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connector = container.querySelector('.phase-connector');
      expect(connector).toHaveClass('completed');
    });

    it('applies "pending" class to connector after a non-completed (active) phase', () => {
      const phases = [
        createPhase({ id: 'a', status: 'active' }),
        createPhase({ id: 'b', status: 'pending' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connector = container.querySelector('.phase-connector');
      expect(connector).toHaveClass('pending');
    });

    it('applies "pending" class to connector after a pending phase', () => {
      const phases = [
        createPhase({ id: 'a', status: 'pending' }),
        createPhase({ id: 'b', status: 'pending' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connector = container.querySelector('.phase-connector');
      expect(connector).toHaveClass('pending');
    });

    it('uses green connector after completed, gray after non-completed in mixed sequence', () => {
      const phases = [
        createPhase({ id: 'a', status: 'completed' }),
        createPhase({ id: 'b', status: 'completed' }),
        createPhase({ id: 'c', status: 'active' }),
        createPhase({ id: 'd', status: 'pending' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const connectors = container.querySelectorAll('.phase-connector');
      expect(connectors).toHaveLength(3);
      // After phase 0 (completed) → completed
      expect(connectors[0]).toHaveClass('completed');
      // After phase 1 (completed) → completed
      expect(connectors[1]).toHaveClass('completed');
      // After phase 2 (active) → pending
      expect(connectors[2]).toHaveClass('pending');
    });
  });

  describe('container and structure', () => {
    it('renders a root element with class "progress-indicator"', () => {
      const { container } = render(<ProgressIndicator phases={[]} />);
      expect(container.querySelector('.progress-indicator')).toBeInTheDocument();
    });

    it('renders phase items inside the progress-indicator', () => {
      const phases = [createPhase({ id: 'a' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const indicator = container.querySelector('.progress-indicator');
      const item = indicator?.querySelector('.phase-item');
      expect(item).toBeInTheDocument();
    });

    it('orders phase items in the same order as the phases prop', () => {
      const phases = [
        createPhase({ id: 'first', label: 'First' }),
        createPhase({ id: 'second', label: 'Second' }),
        createPhase({ id: 'third', label: 'Third' }),
      ];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const items = container.querySelectorAll('.phase-item');
      expect(items[0]).toHaveTextContent('First');
      expect(items[1]).toHaveTextContent('Second');
      expect(items[2]).toHaveTextContent('Third');
    });

    it('each phase-item contains a phase-icon and a phase-label', () => {
      const phases = [createPhase({ id: 'a', icon: '🔍', label: 'Search' })];
      const { container } = render(<ProgressIndicator phases={phases} />);
      const item = container.querySelector('.phase-item')!;
      expect(item.querySelector('.phase-icon')).toBeInTheDocument();
      expect(item.querySelector('.phase-label')).toBeInTheDocument();
    });
  });
});

/**
 * Tests for develop renderer types and the buildDevelopState helper.
 */

import { describe, it, expect } from 'vitest';

import type {
  WorkflowRunState,
  WorkflowSummary,
  AgentWindowState,
  PhaseDescriptor,
  LogEntry,
} from '../../../types';
import { buildDevelopState } from '../types';
import type {
  DevelopPhaseInfo,
  DevelopAgentInfo,
  DevelopRendererState,
} from '../types';

// ─── Helpers ────────────────────────────────────────────────────────────────

function createPhase(id: string, label?: string, icon?: string): PhaseDescriptor {
  return { id, label: label ?? id, icon: icon ?? '🔵' };
}

function createAgentWindow(agentId: string, overrides: Partial<AgentWindowState> = {}): AgentWindowState {
  return {
    agentId,
    profile: 'default',
    active: false,
    log: [],
    ...overrides,
  };
}

function createSummary(overrides: Partial<WorkflowSummary> = {}): WorkflowSummary {
  const sidebar = overrides.sidebar ?? {
    title: 'Test',
    indicator: '…',
    phases: [],
  };
  return {
    id: 'test-run',
    workflowName: 'Test Workflow',
    status: 'running',
    startedAt: new Date().toISOString(),
    ...overrides,
    sidebar,
  };
}

function createRunState(overrides: Partial<WorkflowRunState> = {}): WorkflowRunState {
  return {
    summary: createSummary(),
    agents: new Map(),
    currentPhase: '',
    completedPhases: [],
    ...overrides,
  };
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('buildDevelopState', () => {
  describe('phases', () => {
    it('should return empty phases array when sidebar has no phases', () => {
      const summary = createSummary({ sidebar: { title: 'No phases', indicator: '…' } });
      const state = createRunState({ summary });
      const result = buildDevelopState(state);
      expect(result.phases).toEqual([]);
    });

    it('should return empty phases array when sidebar.phases is undefined', () => {
      const summary = createSummary({ sidebar: { title: 'No phases', indicator: '…', phases: undefined } });
      const state = createRunState({ summary });
      const result = buildDevelopState(state);
      expect(result.phases).toEqual([]);
    });

    it('should mark a phase as completed when its id is in completedPhases', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1', 'Phase 1', '📋'),
        createPhase('phase-2', 'Phase 2', '⚙️'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-2',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases).toHaveLength(2);
      expect(result.phases[0].status).toBe('completed');
      expect(result.phases[1].status).toBe('active');
    });

    it('should mark a phase as active when it equals currentPhase and is not in completedPhases', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1'),
        createPhase('phase-2'),
        createPhase('phase-3'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-2',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0].status).toBe('completed');
      expect(result.phases[1].status).toBe('active');
      expect(result.phases[2].status).toBe('pending');
    });

    it('should mark a phase as pending when it is neither completed nor active', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1'),
        createPhase('phase-2'),
        createPhase('phase-3'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-1',
        completedPhases: [],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0].status).toBe('active');
      expect(result.phases[1].status).toBe('pending');
      expect(result.phases[2].status).toBe('pending');
    });

    it('should prefer completed status over active when phase is in both completedPhases and currentPhase', () => {
      const phases: PhaseDescriptor[] = [createPhase('phase-1')];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-1',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0].status).toBe('completed');
    });

    it('should preserve id, label, and icon from PhaseDescriptor', () => {
      const phases: PhaseDescriptor[] = [
        { id: 'research', label: 'Research', icon: '🔍' },
        { id: 'implement', label: 'Implement', icon: '⚙️' },
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'implement',
        completedPhases: ['research'],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0]).toEqual({
        id: 'research',
        label: 'Research',
        icon: '🔍',
        status: 'completed',
      });
      expect(result.phases[1]).toEqual({
        id: 'implement',
        label: 'Implement',
        icon: '⚙️',
        status: 'active',
      });
    });
  });

  describe('agents', () => {
    it('should return empty agents array when runState has no agents', () => {
      const state = createRunState({ agents: new Map() });
      const result = buildDevelopState(state);
      expect(result.agents).toEqual([]);
    });

    it('should convert agents Map to sorted array by agentId', () => {
      const agents = new Map<string, AgentWindowState>([
        ['agent-beta', createAgentWindow('agent-beta', { profile: 'beta', active: true })],
        ['agent-alpha', createAgentWindow('agent-alpha', { profile: 'alpha', active: false })],
        ['agent-gamma', createAgentWindow('agent-gamma', { profile: 'gamma', active: true })],
      ]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents).toHaveLength(3);
      expect(result.agents[0].agentId).toBe('agent-alpha');
      expect(result.agents[1].agentId).toBe('agent-beta');
      expect(result.agents[2].agentId).toBe('agent-gamma');
    });

    it('should include all agent properties', () => {
      const logEntry: LogEntry = {
        id: 'log-1',
        timestamp: new Date().toISOString(),
        type: 'text',
        content: 'hello',
      };
      const agent = createAgentWindow('agent-1', {
        profile: 'worker',
        taskId: 'task-42',
        active: true,
        log: [logEntry],
      });
      const agents = new Map([['agent-1', agent]]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents[0]).toEqual({
        agentId: 'agent-1',
        profile: 'worker',
        taskId: 'task-42',
        active: true,
        log: [logEntry],
      });
    });

    it('should handle agents without taskId', () => {
      const agent = createAgentWindow('agent-1', {
        profile: 'solo',
        active: false,
        taskId: undefined,
      });
      const agents = new Map([['agent-1', agent]]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents[0].taskId).toBeUndefined();
    });

    it('should preserve log entries array order', () => {
      const entry1: LogEntry = { id: '1', timestamp: '2024-01-01T00:00:00Z', type: 'text', content: 'first' };
      const entry2: LogEntry = { id: '2', timestamp: '2024-01-01T00:00:01Z', type: 'text', content: 'second' };
      const entry3: LogEntry = { id: '3', timestamp: '2024-01-01T00:00:02Z', type: 'text', content: 'third' };
      const agent = createAgentWindow('agent-1', {
        log: [entry1, entry2, entry3],
      });
      const agents = new Map([['agent-1', agent]]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents[0].log).toEqual([entry1, entry2, entry3]);
    });
  });

  describe('currentPhase', () => {
    it('should return the currentPhase from runState', () => {
      const state = createRunState({ currentPhase: 'phase-3' });
      const result = buildDevelopState(state);
      expect(result.currentPhase).toBe('phase-3');
    });

    it('should return empty string when currentPhase is empty', () => {
      const state = createRunState({ currentPhase: '' });
      const result = buildDevelopState(state);
      expect(result.currentPhase).toBe('');
    });
  });

  describe('integration', () => {
    it('should produce correct DevelopRendererState from a realistic WorkflowRunState', () => {
      const phases: PhaseDescriptor[] = [
        { id: 'plan', label: 'Plan', icon: '📋' },
        { id: 'code', label: 'Code', icon: '💻' },
        { id: 'test', label: 'Test', icon: '🧪' },
        { id: 'deploy', label: 'Deploy', icon: '🚀' },
      ];

      const logA: LogEntry[] = [
        { id: 'a1', timestamp: '2024-01-01T00:00:00Z', type: 'text', content: 'Starting' },
      ];
      const logB: LogEntry[] = [
        { id: 'b1', timestamp: '2024-01-01T00:00:05Z', type: 'thinking', content: 'Thinking...' },
        { id: 'b2', timestamp: '2024-01-01T00:00:06Z', type: 'decision', content: 'Decided' },
      ];

      const agents = new Map<string, AgentWindowState>([
        [
          'planner',
          {
            agentId: 'planner',
            profile: 'Planner Agent',
            taskId: 'task-plan',
            active: false,
            log: logA,
          },
        ],
        [
          'coder',
          {
            agentId: 'coder',
            profile: 'Coder Agent',
            taskId: 'task-code',
            active: true,
            log: logB,
          },
        ],
      ]);

      const summary = createSummary({
        id: 'run-integration',
        workflowName: 'Build Feature',
        status: 'running',
        sidebar: {
          title: 'Build Feature',
          indicator: '…',
          phases,
        },
        startedAt: '2024-01-01T00:00:00Z',
      });

      const runState: WorkflowRunState = {
        summary,
        agents,
        currentPhase: 'code',
        completedPhases: ['plan'],
      };

      const result = buildDevelopState(runState);

      // Verify phases
      expect(result.phases).toHaveLength(4);
      expect(result.phases[0]).toEqual({ id: 'plan', label: 'Plan', icon: '📋', status: 'completed' });
      expect(result.phases[1]).toEqual({ id: 'code', label: 'Code', icon: '💻', status: 'active' });
      expect(result.phases[2]).toEqual({ id: 'test', label: 'Test', icon: '🧪', status: 'pending' });
      expect(result.phases[3]).toEqual({ id: 'deploy', label: 'Deploy', icon: '🚀', status: 'pending' });

      // Verify agents (sorted by agentId: coder before planner)
      expect(result.agents).toHaveLength(2);
      expect(result.agents[0].agentId).toBe('coder');
      expect(result.agents[0].profile).toBe('Coder Agent');
      expect(result.agents[0].taskId).toBe('task-code');
      expect(result.agents[0].active).toBe(true);
      expect(result.agents[0].log).toEqual(logB);

      expect(result.agents[1].agentId).toBe('planner');
      expect(result.agents[1].profile).toBe('Planner Agent');
      expect(result.agents[1].taskId).toBe('task-plan');
      expect(result.agents[1].active).toBe(false);
      expect(result.agents[1].log).toEqual(logA);

      // Verify currentPhase
      expect(result.currentPhase).toBe('code');
    });
  });
});

/**
 * Frontend types for the engin web interface.
 *
 * Mirrors the backend protocol types from src/web/types.ts (T02) but
 * does NOT import from the backend.  The additional frontend-specific
 * types (WorkflowRunState, AppGlobalState) manage UI state client-side.
 */

// ─── Shared value types (mirrored from T02) ─────────────────────────────────

export interface PhaseDescriptor {
  id: string;
  label: string;
  icon: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type:
    | 'text'
    | 'thinking'
    | 'tool_call'
    | 'tool_call_start'
    | 'tool_call_end'
    | 'decision'
    | 'error';
  content: string;
  metadata?: Record<string, unknown>;
}

export interface AgentWindowState {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface SidebarInfo {
  title: string;
  indicator: string;
  phases?: PhaseDescriptor[];
}

export interface WorkflowSummary {
  id: string;
  workflowName: string;
  status: 'running' | 'completed' | 'failed';
  sidebar: SidebarInfo;
  startedAt: string;
  completedAt?: string;
}

// ─── Server → Client messages (mirrored from T02) ───────────────────────────

export type ServerMessage =
  | { type: 'init'; workflows: WorkflowSummary[] }
  | { type: 'workflow_started'; summary: WorkflowSummary }
  | { type: 'workflow_sidebar'; workflowId: string; sidebar: SidebarInfo }
  | { type: 'workflow_phase'; workflowId: string; phase: string; completed: string[] }
  | { type: 'workflow_complete'; summary: WorkflowSummary }
  | { type: 'workflow_failed'; summary: WorkflowSummary; error: string; phase: string }
  | { type: 'agent_spawned'; workflowId: string; agent: AgentWindowState }
  | { type: 'agent_log'; workflowId: string; agentId: string; entry: LogEntry }
  | { type: 'agent_complete'; workflowId: string; agentId: string };

// ─── Client → Server messages (mirrored from T02) ───────────────────────────

export type ClientMessage =
  | { type: 'start_workflow'; workflowName: string; taskPrompt: string; maxConcurrent?: number }
  | { type: 'select_workflow'; workflowId: string }
  | { type: 'cancel_workflow'; workflowId: string };

// ─── Frontend-specific state types ──────────────────────────────────────────

export interface WorkflowRunState {
  summary: WorkflowSummary;
  agents: Map<string, AgentWindowState>;
  currentPhase: string;
  completedPhases: string[];
}

export interface AppGlobalState {
  workflows: WorkflowSummary[];
  selectedRunId: string | null;
  runStates: Map<string, WorkflowRunState>;
}

// ─── Type guard ─────────────────────────────────────────────────────────────

export function isServerMessage(data: unknown): data is ServerMessage {
  return typeof data === 'object' && data !== null && 'type' in data;
}

